<template>
  <section class="admin-page settings-page"><PageHeader title="系统设置" description="运行环境、数据库状态与开发工具"><template #actions><t-button variant="outline" :loading="refreshing" @click="load(true)"><template #icon><i-refresh theme="outline" /></template>刷新</t-button></template></PageHeader><LoadingState v-if="loading"/><ErrorState v-else-if="loadError" :message="loadError" retryable @retry="load()"/><template v-else><section class="runtime-strip"><div><span>Node.js</span><strong>{{overview.runtime.nodeVersion}}</strong></div><div><span>平台</span><strong>{{overview.runtime.platform}}</strong></div><div><span>环境</span><strong>{{overview.runtime.environment}}</strong></div><div><span>数据表</span><strong>{{overview.database.tables.length}}</strong></div></section><section class="data-section"><div class="section-heading"><h2>开发工具</h2></div><div class="setting-row"><div><strong>AI 调试工具</strong><small>运行时开关</small></div><t-switch :value="overview.development.aiDevToolsEnabled" :loading="saving" :disabled="!overview.capabilities.updateDevelopment" @change="changeDevelopment"/></div></section><p v-if="operationMessage" class="operation-message" :class="{error:operationFailed}" role="status">{{operationMessage}}</p><section class="data-section"><div class="section-heading"><h2>数据库表</h2><span>{{overview.database.tables.length}} 张</span></div><div class="table-scroll"><table><thead><tr><th>表名</th><th>记录数</th></tr></thead><tbody><tr v-for="table in overview.database.tables" :key="table.name"><td><code>{{table.name}}</code></td><td>{{table.rowCount}}</td></tr></tbody></table></div></section></template></section>
</template>
<script setup lang="ts">
import{onMounted,ref}from"vue";import PageHeader from"../components/PageHeader.vue";import LoadingState from"../components/LoadingState.vue";import ErrorState from"../components/ErrorState.vue";import{adminErrorText,getSystemOverview,updateDevelopmentSettings,type SystemOverview}from"../api/adminApi";
const empty=():SystemOverview=>({database:{tables:[]},development:{aiDevToolsEnabled:false},runtime:{nodeVersion:"-",platform:"-",environment:"-"},capabilities:{updateDevelopment:false,clearDatabase:false,importDatabase:false,exportDatabase:false}});const overview=ref(empty());const loading=ref(true);const refreshing=ref(false);const loadError=ref("");const saving=ref(false);const operationMessage=ref("");const operationFailed=ref(false);async function load(silent=false){if(silent)refreshing.value=true;else loading.value=true;loadError.value="";try{overview.value=await getSystemOverview()}catch(cause){loadError.value=adminErrorText(cause,"系统状态加载失败")}finally{loading.value=false;refreshing.value=false}}async function changeDevelopment(value:unknown){const enabled=value===true;saving.value=true;try{await updateDevelopmentSettings(enabled);await load(true);operationFailed.value=false;operationMessage.value="开发工具设置已更新"}catch(cause){operationFailed.value=true;operationMessage.value=adminErrorText(cause,"开发工具设置更新失败")}finally{saving.value=false}}onMounted(()=>load());
</script>
<style scoped lang="scss">
.admin-page{width:min(100%,1120px);margin:0 auto}.runtime-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:12px;border:1px solid var(--stars-border);border-radius:6px;background:#fff}.runtime-strip div{display:grid;gap:4px;padding:12px 14px;border-right:1px solid var(--stars-border)}.runtime-strip div:last-child{border:0}.runtime-strip span,.setting-row small{color:var(--stars-text-muted);font-size:11px}.data-section{margin-bottom:12px;border:1px solid var(--stars-border);border-radius:6px;background:#fff}.section-heading{display:flex;justify-content:space-between;padding:12px 14px;border-bottom:1px solid var(--stars-border)}.section-heading h2{margin:0;font-size:14px}.section-heading span{color:var(--stars-text-muted);font-size:12px}.setting-row{display:flex;align-items:center;justify-content:space-between;padding:13px 14px}.setting-row div{display:grid;gap:3px}.operation-message{margin:0 0 12px;padding:9px 12px;border-left:3px solid var(--stars-brand);background:#fff;color:var(--stars-text-muted);font-size:12px}.operation-message.error{border-color:#dc2626;color:#b91c1c}.table-scroll{max-height:480px;overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:10px 14px;border-bottom:1px solid var(--stars-border);text-align:left}th{color:var(--stars-text-muted);font-weight:500}code{font-size:11px}@media(max-width:680px){.runtime-strip{grid-template-columns:repeat(2,minmax(0,1fr))}.runtime-strip div:nth-child(2){border-right:0}.runtime-strip div:nth-child(-n+2){border-bottom:1px solid var(--stars-border)}}
</style>
